/**
 * defineModel end to end: the demo kon `kon-notes`
 * ============================================================================
 *
 * Two models declared ONCE (tests/unit/fixtures/kon-notes/notes.model.ts)
 * and their migration GENERATED by `kitsuden makemigrations` (0000_models.sql). Here
 * the kon is mounted the way the host mounts it: PGlite with a NON-superuser
 * role (otherwise Postgres skips RLS and everything would be green), the engine's
 * per-request RLS transaction and the SDK router.
 *
 * What it guards:
 *   · model → table: the Drizzle table and the migration's are the same;
 *   · REST: CRUD, 422 problem+json validation, 404 without leaking existence, 409;
 *   · isolation: each account sees its own, the admin everything, the anonymous nothing;
 *   · agent scopes: no scope nothing, `note:read` does not write, `note:write`
 *     does, a denial beats `admin`, `user:act` does not write;
 *   · real RLS, with SABOTAGE: the policy is weakened and the probe has to
 *     detect it; it is restored and isolates again;
 *   · OpenAPI 3.1 (validated) and MCP tools from the same declarations.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { PGlite } from "@electric-sql/pglite";
import {
  field,
  defineModel,
  rlsPolicies,
  scopesThatGrant,
  type KonContext,
} from "@kitsuden/shared";
import { Validator } from "@seriousme/openapi-schema-validator";
import { sql } from "drizzle-orm";
import { getTableConfig } from "drizzle-orm/pg-core";
import { drizzle } from "drizzle-orm/pglite";
import { Hono, type MiddlewareHandler } from "hono";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

import {
  commonComponents,
  mcpTool,
  openApiOperation,
} from "../../apps/api/src/lib/operations-openapi";
import { httpProblems } from "../../apps/api/src/middleware/problems-http";
import { respondError } from "../../packages/engine/src/errors";
import { modelTable } from "../../packages/engine/src/models";
import { operationsOf } from "../../packages/engine/src/operations";
import { theRequestDb, rlsTransaction } from "../../packages/engine/src/rls-request";

import { kon } from "./fixtures/kon-notes/index";
import { category, note } from "./fixtures/kon-notes/notes.model";

const ROOT = resolve(__dirname, "../..");
const read = (route: string) => readFileSync(resolve(ROOT, route), "utf8");

let client: PGlite;
let db: ReturnType<typeof drizzle>;
let app: Hono;

type Who = { id: string; role: string; scopes?: string[] };
const ACCOUNTS: Record<string, Who> = {
  ana: { id: "ana", role: "user" },
  bob: { id: "bob", role: "user" },
  edi: { id: "edi", role: "editor" },
  adm: { id: "adm", role: "admin" },
};

/** Who is asking: `x-who` (account) or `x-agent` (comma-separated scopes). */
const session: MiddlewareHandler = async (c, next) => {
  const who = c.req.header("x-who");
  const agent = c.req.header("x-agent");
  if (who && ACCOUNTS[who]) c.set("user" as never, ACCOUNTS[who] as never);
  if (agent !== undefined) {
    c.set(
      "user" as never,
      { id: "ag_1", role: "agent", scopes: agent.split(",").filter(Boolean) } as never
    );
  }
  await next();
};
const requireAuth: MiddlewareHandler = async (c, next) => {
  if (!c.get("user" as never)) return c.json({ error: "Unauthorized" }, 401);
  await next();
};
const optionalAuth: MiddlewareHandler = async (_c, next) => next();

const rows = (r: unknown) => ((r as { rows?: unknown[] }).rows ?? r) as Record<string, unknown>[];

beforeAll(async () => {
  client = new PGlite();
  await client.exec(read("apps/api/src/db/agent-functions.sql"));
  await client.exec(read("tests/unit/fixtures/kon-notes/migrations/0000_models.sql"));
  await client.exec(`
    CREATE ROLE rls_app NOLOGIN;
    GRANT USAGE ON SCHEMA public TO rls_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO rls_app;
    SET ROLE rls_app;
  `);
  const r = await client.query<{ su: boolean }>(
    `SELECT rolsuper OR rolbypassrls AS su FROM pg_roles WHERE rolname = current_user`
  );
  expect(r.rows[0]?.su).toBe(false);

  db = drizzle(client);
  const ctx = {
    db: { instance: theRequestDb(db) },
    auth: { requireAuth, optionalAuth },
  } as unknown as KonContext;
  app = new Hono();
  app.onError((err, c) => respondError(c, err));
  // The same pieces the host puts in front of every kon route:
  // problem+json on the way out and the per-request RLS transaction.
  app.use("/api/*", httpProblems());
  app.use("*", session);
  app.use("/api/*", rlsTransaction(db));
  app.route("/api/notes", kon.createRouter(ctx));
});

afterAll(async () => {
  await client?.close();
});

function request(
  route: string,
  o: { who?: string; agent?: string[]; method?: string; body?: unknown } = {}
) {
  const headers: Record<string, string> = { "content-type": "application/json" };
  if (o.who) headers["x-who"] = o.who;
  if (o.agent) headers["x-agent"] = o.agent.join(",");
  return app.request(`/api/notes${route}`, {
    method: o.method ?? "GET",
    headers,
    body: o.body === undefined ? undefined : JSON.stringify(o.body),
  });
}

async function createNote(who: string, title: string): Promise<Record<string, unknown>> {
  const res = await request("/notes", { who, method: "POST", body: { title } });
  expect(res.status, await res.clone().text()).toBe(201);
  return (await res.json()) as Record<string, unknown>;
}

// ═════════════════════════════════════════════════════════════════════════════

describe("model → table", () => {
  it("the Drizzle table has the columns the generated migration created", async () => {
    const drizzleCols = getTableConfig(modelTable(note))
      .columns.map((c) => c.name)
      .sort();
    const sqlCols = rows(
      await db.execute(
        sql`SELECT column_name FROM information_schema.columns WHERE table_name = 'notes'`
      )
    )
      .map((f) => String(f.column_name))
      .sort();
    expect(drizzleCols).toEqual(sqlCols);
    expect(sqlCols).toEqual([
      "body",
      "created_at",
      "due_at",
      "id",
      "meta",
      "owner_id",
      "pinned",
      "priority",
      "slug",
      "status",
      "title",
      "updated_at",
    ]);
  });

  it("both tables are born with RLS ENABLE and FORCE", async () => {
    const r = rows(
      await db.execute(
        sql`SELECT relname, relrowsecurity AS rls, relforcerowsecurity AS forced FROM pg_class WHERE relname IN ('notes', 'categories') ORDER BY relname`
      )
    );
    expect(r).toEqual([
      { relname: "categories", rls: true, forced: true },
      { relname: "notes", rls: true, forced: true },
    ]);
  });

  it("the kon declares its tables and six operations per model", () => {
    expect(kon.tables).toEqual(["notes", "categories"]);
    expect(operationsOf(kon).map((o) => o.id)).toEqual([
      "describe-note",
      "list-notes",
      "get-note",
      "create-note",
      "update-note",
      "delete-note",
      "describe-category",
      "list-categories",
      "get-category",
      "create-category",
      "update-category",
      "delete-category",
    ]);
  });
});

describe("REST: CRUD with validation and problem+json", () => {
  it("create → 201 with owner and the column's default values", async () => {
    const n = await createNote("ana", "Buy bread");
    expect(n).toMatchObject({
      title: "Buy bread",
      ownerId: "ana",
      status: "draft",
      priority: 0,
      pinned: false,
    });
    expect(typeof n.id).toBe("string");
  });

  it("the owner is not chosen: an ownerId in the body is an unknown field (422)", async () => {
    const res = await request("/notes", {
      who: "ana",
      method: "POST",
      body: { title: "x", ownerId: "bob" },
    });
    // The owner cannot be forged: the field does not exist in the input (422 with the list of valid ones).
    expect(res.status).toBe(422);
    expect(JSON.stringify(await res.json())).toContain("ownerId");
  });

  it("a misspelled field is 422 KITSUDEN_E_VALIDATION with «did you mean?»", async () => {
    const res = await request("/notes", { who: "ana", method: "POST", body: { titel: "x" } });
    expect(res.status).toBe(422);
    const body = JSON.stringify(await res.json());
    expect(body).toContain("KITSUDEN_E_VALIDATION");
    expect(body).toContain("title");
  });

  it("values outside the model: enum, range and length → 422", async () => {
    for (const bad of [
      { title: "x", status: "deleted" },
      { title: "x", priority: 9 },
      { title: "x".repeat(201) },
    ]) {
      const res = await request("/notes", { who: "ana", method: "POST", body: bad });
      expect(res.status, JSON.stringify(bad)).toBe(422);
    }
  });

  it("read, list, edit and delete", async () => {
    const n = await createNote("ana", "Call mom");
    const one = await request(`/notes/${n.id}`, { who: "ana" });
    expect(one.status).toBe(200);
    const list = (await (await request("/notes?limit=50&sort=title", { who: "ana" })).json()) as {
      data: { id: string }[];
      total: number;
      limit: number;
    };
    expect(list.data.some((f) => f.id === n.id)).toBe(true);
    expect(list.limit).toBe(50);
    const edited = await request(`/notes/${n.id}`, {
      who: "ana",
      method: "PATCH",
      body: { status: "published", dueAt: "2026-11-01T10:00:00Z", meta: { a: 1 } },
    });
    expect(edited.status).toBe(200);
    expect(await edited.json()).toMatchObject({
      status: "published",
      meta: { a: 1 },
      title: "Call mom",
    });
    const filter = (await (await request("/notes?status=published", { who: "ana" })).json()) as {
      data: { id: string }[];
    };
    expect(filter.data.map((f) => f.id)).toContain(n.id);
    expect((await request(`/notes/${n.id}`, { who: "ana", method: "DELETE" })).status).toBe(204);
    expect((await request(`/notes/${n.id}`, { who: "ana" })).status).toBe(404);
  });

  it("an id that is not a uuid is 422, not a Postgres 500", async () => {
    expect((await request("/notes/not-a-uuid", { who: "ana" })).status).toBe(422);
  });

  it("the model descriptor (what the panel paints)", async () => {
    const res = await request("/notes/_model", { who: "ana" });
    expect(res.status).toBe(200);
    const d = (await res.json()) as {
      scopes: unknown;
      fields: { key: string }[];
      withOwner: boolean;
    };
    expect(d.scopes).toEqual({ read: "note:read", write: "note:write" });
    expect(d.withOwner).toBe(true);
    expect(d.fields.map((c) => c.key)).toEqual([
      "title",
      "body",
      "status",
      "priority",
      "pinned",
      "dueAt",
      "slug",
      "meta",
    ]);
  });
});

describe("isolation by owner (the two walls: handler and RLS)", () => {
  it("bob cannot see, read, edit or delete ana's (404, without leaking existence)", async () => {
    const n = await createNote("ana", "Ana's secret");
    const fromBob = (await (await request("/notes?limit=100", { who: "bob" })).json()) as {
      data: { id: string }[];
      total: number;
    };
    expect(fromBob.data.find((f) => f.id === n.id)).toBeUndefined();
    expect((await request(`/notes/${n.id}`, { who: "bob" })).status).toBe(404);
    expect(
      (await request(`/notes/${n.id}`, { who: "bob", method: "PATCH", body: { title: "mine" } }))
        .status
    ).toBe(404);
    expect((await request(`/notes/${n.id}`, { who: "bob", method: "DELETE" })).status).toBe(404);
    expect((await request(`/notes/${n.id}`, { who: "ana" })).status).toBe(200);
  });

  it("the admin sees everything; the editor (staff) does not own other people's notes", async () => {
    const n = await createNote("ana", "For the admin");
    expect((await request(`/notes/${n.id}`, { who: "adm" })).status).toBe(200);
    expect((await request(`/notes/${n.id}`, { who: "edi" })).status).toBe(404);
  });

  it("no session: 401 on notes; categories (public) can be read", async () => {
    expect((await request("/notes")).status).toBe(401);
    expect((await request("/categories")).status).toBe(200);
    expect((await request("/categories", { method: "POST", body: { name: "x" } })).status).toBe(
      401
    );
  });

  it("categories: the team writes, not any account; repeating the unique one is 409", async () => {
    expect(
      (await request("/categories", { who: "ana", method: "POST", body: { name: "Leisure" } }))
        .status
    ).toBe(403);
    expect(
      (await request("/categories", { who: "edi", method: "POST", body: { name: "Leisure" } }))
        .status
    ).toBe(201);
    const repeated = await request("/categories", {
      who: "edi",
      method: "POST",
      body: { name: "Leisure" },
    });
    expect(repeated.status).toBe(409);
    expect(repeated.headers.get("content-type")).toContain("application/problem+json");
    expect(((await repeated.json()) as { code: string }).code).toBe("KITSUDEN_E_CONFLICT");
    const publicRows = (await (await request("/categories")).json()) as {
      data: { name: string }[];
    };
    expect(publicRows.data.map((c) => c.name)).toContain("Leisure");
  });
});

describe("agent scopes: an agent never writes by default", () => {
  it("no scopes (or only connection ones): 403 on reading and writing notes", async () => {
    for (const scopes of [[], ["mcp:connect", "mcp:read"]]) {
      expect((await request("/notes", { agent: scopes })).status).toBe(403);
      expect(
        (await request("/notes", { agent: scopes, method: "POST", body: { title: "x" } })).status
      ).toBe(403);
    }
  });

  it("acting as a user does not grant write on a model", async () => {
    expect(
      (await request("/notes", { agent: ["user:act"], method: "POST", body: { title: "x" } }))
        .status
    ).toBe(403);
  });

  it("note:read reads (its rows) but does not write", async () => {
    const res = await request("/notes", { agent: ["note:read"] });
    expect(res.status).toBe(200);
    expect(((await res.json()) as { data: unknown[] }).data).toEqual([]);
    expect(
      (await request("/notes", { agent: ["note:read"], method: "POST", body: { title: "x" } }))
        .status
    ).toBe(403);
  });

  it("note:write creates, and the row belongs to the agent; the fine-grained kon:notes:create-note too", async () => {
    const res = await request("/notes", {
      agent: ["note:write"],
      method: "POST",
      body: { title: "from the agent" },
    });
    expect(res.status).toBe(201);
    expect(((await res.json()) as { ownerId: string }).ownerId).toBe("ag_1");
    const fine = await request("/notes", {
      agent: ["kon:notes:create-note"],
      method: "POST",
      body: { title: "fine-grained" },
    });
    expect(fine.status).toBe(201);
    // The fine-grained create does not open delete.
    const id = ((await fine.json()) as { id: string }).id;
    expect(
      (await request(`/notes/${id}`, { agent: ["kon:notes:create-note"], method: "DELETE" })).status
    ).toBe(403);
  });

  it("a denial beats everything, admin included", async () => {
    for (const scopes of [
      ["note:write", "!note:write"],
      ["admin", "!note:write"],
      ["admin", "!kon:notes:*"],
    ]) {
      const res = await request("/notes", { agent: scopes, method: "POST", body: { title: "no" } });
      expect(res.status, scopes.join(",")).toBe(403);
    }
  });

  it("notes:* opens the whole kon: sees everyone's notes (and RLS agrees)", async () => {
    await createNote("ana", "Visible to notes:*");
    const res = await request("/notes?limit=100", { agent: ["notes:*"] });
    expect(res.status).toBe(200);
    const body = (await res.json()) as { data: { ownerId: string }[] };
    expect(body.data.some((f) => f.ownerId === "ana")).toBe(true);
  });

  it("category:write: the agent writes to the team's model and RLS lets it", async () => {
    const res = await request("/categories", {
      agent: ["category:write"],
      method: "POST",
      body: { name: "From the agent" },
    });
    expect(res.status, await res.clone().text()).toBe(201);
    expect(
      (await request("/categories", { agent: ["note:read"], method: "POST", body: { name: "No" } }))
        .status
    ).toBe(403);
  });

  it("the scopes that grant creating a note (what the panel shows)", () => {
    const create = operationsOf(kon).find((o) => o.id === "create-note")!;
    const list = scopesThatGrant("kon-notes", create);
    expect(list).toEqual(
      expect.arrayContaining(["kon:notes:create-note", "notes:*", "note:write", "admin"])
    );
    expect(list).not.toContain("note:read");
  });
});

describe("Postgres RLS (the database's wall), with sabotage", () => {
  /** How many rows of `notes` whose owner is NOT `id` does `id` see with the app role. */
  async function foreignSeen(id: string, role: string): Promise<number> {
    return client.transaction(async (tx) => {
      await tx.query(
        "SELECT set_config('app.current_user_id', $1, true), set_config('app.current_user_role', $2, true)",
        [id, role]
      );
      const r = await tx.query<{ n: number }>(
        "SELECT count(*)::int AS n FROM notes WHERE owner_id IS DISTINCT FROM $1",
        [id]
      );
      return Number(r.rows[0]?.n ?? 0);
    });
  }
  /** The probe: neither a stranger nor the anonymous sees other people's rows. */
  async function isolates(): Promise<boolean> {
    return (
      (await foreignSeen("stranger", "user")) === 0 && (await foreignSeen("", "anonymous")) === 0
    );
  }

  it("there are rows from others (otherwise the probe proves nothing)", async () => {
    await createNote("ana", "Row for the probe");
    const r = await client.query<{ n: number }>("SELECT count(*)::int AS n FROM notes");
    // With the app role and no context (the system) everything is visible:
    expect(Number(r.rows[0]?.n)).toBeGreaterThan(0);
  });

  it("isolates: a stranger and the anonymous see zero foreign rows", async () => {
    expect(await isolates()).toBe(true);
  });

  it("SABOTAGE: with the policy weakened the probe detects it, and the handler still isolates; restored, it isolates again", async () => {
    await client.exec(`
      RESET ROLE;
      DROP POLICY "notes_select" ON "notes";
      CREATE POLICY "notes_select" ON "notes" FOR SELECT TO PUBLIC USING (true);
      SET ROLE rls_app;
    `);
    try {
      expect(await isolates()).toBe(false);
      // The second wall (the handler's filter) does not depend on RLS.
      const fromBob = (await (await request("/notes?limit=100", { who: "bob" })).json()) as {
        data: { ownerId: string }[];
      };
      expect(fromBob.data.every((f) => f.ownerId === "bob")).toBe(true);
    } finally {
      // It is restored with the SAME SQL the migration generates.
      const { modelSnapshot } = await import("@kitsuden/shared");
      await client.exec(
        `RESET ROLE;\n${rlsPolicies(modelSnapshot(note, "notes")).join("\n")}\nSET ROLE rls_app;`
      );
    }
    expect(await isolates()).toBe(true);
  });

  it("INSERT with someone else's owner: RLS rejects it even if the handler were not there", async () => {
    await expect(
      client.transaction(async (tx) => {
        await tx.query(
          "SELECT set_config('app.current_user_id', 'bob', true), set_config('app.current_user_role', 'user', true)"
        );
        await tx.query("INSERT INTO notes (title, owner_id) VALUES ('forged', 'ana')");
      })
    ).rejects.toThrow(/row-level security/);
  });
});

describe("OpenAPI 3.1 and MCP come from the same declaration", () => {
  const ops = operationsOf(kon);

  it("the OpenAPI document of the kon's operations is VALID", async () => {
    const doc = {
      openapi: "3.1.0",
      info: { title: "kon-notes", version: "test" },
      servers: [{ url: "http://localhost:3000/api" }],
      paths: {} as Record<string, Record<string, unknown>>,
      components: commonComponents(),
    };
    for (const op of ops) {
      const g = openApiOperation("kon-notes", "/api/notes", op);
      (doc.paths[g.path] ??= {})[g.method] = g.operation;
    }
    expect(Object.keys(doc.paths).sort()).toEqual([
      "/notes/categories",
      "/notes/categories/_model",
      "/notes/categories/{id}",
      "/notes/notes",
      "/notes/notes/_model",
      "/notes/notes/{id}",
    ]);
    const r = await new Validator().validate(doc);
    expect(r.errors ?? [], JSON.stringify(r.errors, null, 1)?.slice(0, 3000)).toEqual([]);
  });

  it("create accepts Idempotency-Key and requires title; delete is sensitive", () => {
    const create = openApiOperation(
      "kon-notes",
      "/api/notes",
      ops.find((o) => o.id === "create-note")!
    ).operation as {
      parameters: { name: string; in: string }[];
      requestBody: {
        content: { "application/json": { schema: { required?: string[]; properties: object } } };
      };
    };
    expect(create.parameters.some((p) => p.name === "Idempotency-Key" && p.in === "header")).toBe(
      true
    );
    const schema = create.requestBody.content["application/json"].schema;
    expect(schema.required).toEqual(["title"]);
    expect(Object.keys(schema.properties)).not.toContain("ownerId");
    const remove = openApiOperation(
      "kon-notes",
      "/api/notes",
      ops.find((o) => o.id === "delete-note")!
    ).operation;
    expect(JSON.stringify(remove)).toContain('"sensitive":true');
  });

  it("MCP tools: stable names, read and destroy announced", () => {
    const tools = ops.map((op) => mcpTool("kon-notes", "/api/notes", op)!);
    expect(tools.map((h) => h.name)).toContain("notes__create-note");
    const list = tools.find((h) => h.name === "notes__list-notes")!;
    expect(list.annotations.readOnlyHint).toBe(true);
    const remove = tools.find((h) => h.name === "notes__delete-note")!;
    expect(remove.annotations.destructiveHint).toBe(true);
    const create = tools.find((h) => h.name === "notes__create-note")!;
    expect(JSON.stringify(create.inputSchema)).toContain('"title"');
  });
});

describe("safe by default when declaring", () => {
  const fields = { t: field.text({ required: true }) };
  it("without an access policy there is no model", () => {
    expect(() => defineModel({ name: "x", description: "x", fields } as never)).toThrow(/access/);
  });
  it("public write access does not exist", () => {
    expect(() =>
      defineModel({
        name: "x",
        description: "x",
        fields,
        access: { read: "public", write: "public" },
      } as never)
    ).toThrow(/public write access does not exist/);
  });
  it("a core name cannot be a model (its scope would collide)", () => {
    expect(() =>
      defineModel({
        name: "admin",
        description: "x",
        fields,
        access: { read: "owner", write: "owner" },
      })
    ).toThrow(/is reserved/);
  });
  it("a default value that does not validate is rejected on declaration", () => {
    expect(() =>
      defineModel({
        name: "x",
        description: "x",
        fields: { s: field.enum(["a"], { defaultValue: "b" }) },
        access: { read: "owner", write: "owner" },
      })
    ).toThrow(/default value/);
  });
  it("the category is public to read and team-only to write", () => {
    expect(category.access).toEqual({ read: "public", write: "staff" });
  });
});
